svg.script:
(function () {
  var resolverUrl = "https://cdn.jsdelivr.net/gh/sealiee11/arctic-static@main/assets/resolver-C09Pc7JC.js";
  var bundledWisps = ["wss://wisp.mercurywork.shop/", "wss://arctic.lat/wisp/"];
  var frame = document.getElementById("frame");
  var stage = document.getElementById("stage");
  var statusEl = document.getElementById("status");
  var errorBox = document.getElementById("error");
  var errorText = document.getElementById("errorText");
  var retry = document.getElementById("retry");
  var runtime = null;
  var relayPromise = null;
  var rejectedRelays = new Set();
  var runId = 0;

  function ensureHtmlCompat() {
    var root = document.getElementById("static-scramjet-root");
    var head = document.getElementById("static-scramjet-head");
    if (!head && root) {
      head = document.createElementNS("http://www.w3.org/1999/xhtml", "div");
      head.id = "static-scramjet-head";
      head.style.display = "none";
      root.appendChild(head);
    }
    try {
      if (!document.body && root) {
        Object.defineProperty(document, "body", {
          configurable: true,
          get: function () { return root; }
        });
      }
    } catch (error) {}
    try {
      if (!document.head && head) {
        Object.defineProperty(document, "head", {
          configurable: true,
          get: function () { return head; }
        });
      }
    } catch (error) {}
    try {
      if (!document.documentElement.append) {
        document.documentElement.append = function () {
          var target = document.body || root || document.documentElement;
          return target.append.apply(target, arguments);
        };
      }
    } catch (error) {}
  }

  function normalizeWisp(value) {
    if (typeof value !== "string") return null;
    var text = value.trim();
    if (!/^wss?:\/\//i.test(text)) return null;
    var clean = text.replace(/[?#].*$/, "");
    return clean.endsWith("/") ? clean : clean + "/";
  }

  function params() {
    return new URLSearchParams(window.location.search || "");
  }

  function post(status, detail) {
    if (window.parent !== window) {
      window.parent.postMessage({ type: "arctic-embed", status: status, detail: detail }, "*");
    }
  }

  function decodeTarget(hash) {
    if (!hash) return "";
    if (hash.indexOf("aw1.") === 0) {
      var payload = hash.slice(4).replace(/-/g, "+").replace(/_/g, "/");
      var raw = atob(payload + "=".repeat((4 - payload.length % 4) % 4));
      var bytes = new Uint8Array(raw.length);
      for (var i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
      return new TextDecoder().decode(bytes);
    }
    try {
      return decodeURIComponent(hash);
    } catch {
      return hash;
    }
  }

  function targetOf() {
    var query = params();
    var hashTarget = decodeTarget(window.location.hash.slice(1));
    return hashTarget || query.get("url") || "";
  }

  function setStatus(text) {
    statusEl.textContent = text;
    post("progress", text);
  }

  function showError(message) {
    frame.style.display = "none";
    stage.style.display = "grid";
    errorText.textContent = message;
    errorBox.style.display = "block";
    post("error", message);
  }

  function loadRelays() {
    if (!relayPromise) {
      var query = params();
      var preferred = normalizeWisp(query.get("wisp") || "wss://wisp.mercurywork.shop/");
      var relays = [preferred].concat(bundledWisps.map(normalizeWisp)).filter(Boolean);
      relayPromise = Promise.resolve(Array.from(new Set(relays)));
    }
    return relayPromise;
  }

  async function nextRelay() {
    var relays = await loadRelays();
    return relays.find(function (value) { return !rejectedRelays.has(value); }) || relays[0] || "wss://wisp.mercurywork.shop/";
  }

  async function getRuntime() {
    if (runtime) return runtime;
    ensureHtmlCompat();
    var mod = await import(resolverUrl);
    ensureHtmlCompat();
    await mod.r().catch(function () {});
    ensureHtmlCompat();
    runtime = new mod.R(nextRelay, {
      onWispFailure: function (url) {
        var clean = normalizeWisp(url) || url;
        if (clean && rejectedRelays.size < Math.max(0, bundledWisps.length - 1)) rejectedRelays.add(clean);
      },
      onWispSuccess: function (url) {
        var clean = normalizeWisp(url) || url;
        if (clean) rejectedRelays.delete(clean);
      }
    });
    return runtime;
  }

  async function load() {
    var target = targetOf();
    var token = ++runId;
    if (!target) {
      showError("No address was provided.");
      return;
    }

    errorBox.style.display = "none";
    frame.style.display = "none";
    stage.style.display = "grid";
    setStatus("connecting...");

    try {
      var engine = await getRuntime();
      var query = params();
      await engine.navigate({
        url: target,
        frame: frame,
        backend: query.get("backend") || "scramjet2",
        token: String(token),
        signal: undefined,
        isStale: function () { return token !== runId; },
        onLocationChange: function (url) { post("navigate", url); },
        onStatus: function (info) {
          if (info.phase === "resolving-wisp") setStatus("checking relay...");
          if (info.phase === "connecting") setStatus("starting Scramjet...");
          if (info.phase === "retrying") setStatus("retrying...");
          if (info.phase === "loading") setStatus("loading...");
        }
      });

      if (token !== runId) return;
      stage.style.display = "none";
      frame.style.display = "block";
      post("ready", target);
    } catch (error) {
      if (token === runId) {
        showError(error && error.message ? error.message : "The connection did not finish.");
      }
    }
  }

  retry.addEventListener("click", function () {
    if (runtime) runtime.destroy();
    rejectedRelays.clear();
    relayPromise = null;
    runtime = null;
    load();
  });

  load();
})();
